import sys
import re
from Bio import SeqIO

def calculate_gc(sequence: str) -> float:
    """Calculates the GC percentage of a sequence (case-insensitive)."""
    if not sequence:
        return 0.0

    # Count G and C (case-insensitive)
    gc_count = sequence.count('G') + sequence.count('C') + sequence.count('g') + sequence.count('c')
    total_length = len(sequence)

    return (gc_count / total_length) * 100.0

def extract_gene(header: str) -> str:
    """Extract the gene name from the header string based on the [gene=...] tag."""
    # Look for the pattern [gene=VALUE]
    match = re.search(r'\[gene=([^\]]+)\]', header)
    if match:
        return match.group(1)
    return "UNKNOWN"

def main():
    if len(sys.argv) != 2:
        # If no argument is provided, exit silently as per requirement to print nothing else.
        return

    fasta_path = sys.argv[1]

    try:
        # SeqIO.parse handles multi-record FASTA files efficiently
        for record in SeqIO.parse(fasta_path, "fasta"):
            header = record.description
            sequence = str(record.seq)

            gene = extract_gene(header)
            gc_percent = calculate_gc(sequence)

            # Print output in the required format: GENE<TAB>GC (rounded to 2 decimals)
            print(f"{gene}\t{gc_percent:.2f}")

    except FileNotFoundError:
        # If the file does not exist, exit silently.
        pass
    except Exception:
        # Handle other parsing errors gracefully without printing debug info.
        pass

if __name__ == "__main__":
    main()
